contracts/AuthorizationManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title AuthorizationManager
 * @dev 链创守护 - 版权授权管理合约
 * @notice 管理版权授权、许可发放、授权验证
 */
contract AuthorizationManager is Ownable, AccessControl, ReentrancyGuard {

    // ============ 角色定义 ============
    bytes32 public constant ARBITER_ROLE = keccak256("ARBITER_ROLE");

    // ============ 数据结构 ============

    /// @dev 授权记录结构体
    struct Authorization {
        uint256 id;                 // 授权ID
        uint256 copyrightId;        // 版权记录ID
        address licensor;           // 授权人(版权方)
        address licensee;           // 被授权人
        LicenseType licenseType;    // 授权类型
        uint256 fee;                // 授权费用 (wei)
        uint256 startTime;          // 开始时间
        uint256 endTime;            // 结束时间 (0=永久)
        bool active;                // 是否有效
        uint256 createdAt;          // 创建时间
    }

    enum LicenseType {
        EXCLUSIVE,       // 独家授权
        NON_EXCLUSIVE,   // 非独家授权
        TEMPORARY        // 临时授权
    }

    /// @dev 授权许可结构体
    struct License {
        uint256 id;
        uint256 authorizationId;    // 关联授权ID
        address licensee;           // 被许可人
        string licenseURI;          // 许可证书URI
        uint256 issuedAt;           // 发放时间
        bool valid;                 // 是否有效
    }

    // ============ 状态变量 ============

    uint256 private _authIdCounter;
    uint256 private _licenseIdCounter;

    // 授权记录映射
    mapping(uint256 => Authorization) private _authorizations;

    // 许可映射
    mapping(uint256 => License) private _licenses;

    // 版权ID => 授权ID列表
    mapping(uint256 => uint256[]) private _copyrightAuthorizations;

    // 被授权人 => 授权ID列表
    mapping(address => uint256[]) private _licenseeAuthorizations;

    // 全部授权ID
    uint256[] private _allAuthIds;

    // ============ 事件 ============

    event AuthorizationCreated(
        uint256 indexed authId,
        uint256 indexed copyrightId,
        address indexed licensor,
        address licensee,
        LicenseType licenseType,
        uint256 fee
    );

    event AuthorizationRevoked(
        uint256 indexed authId,
        address indexed revoker
    );

    event LicenseIssued(
        uint256 indexed licenseId,
        uint256 indexed authorizationId,
        address indexed licensee,
        string licenseURI
    );

    event LicenseRevoked(
        uint256 indexed licenseId
    );

    event FeePaid(
        uint256 indexed authId,
        address indexed payer,
        uint256 amount
    );

    // ============ 构造函数 ============

    constructor() Ownable() {
        _transferOwnership(msg.sender);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ARBITER_ROLE, msg.sender);
    }

    // ============ 修饰器 ============

    modifier authExists(uint256 authId) {
        require(_authorizations[authId].id > 0, "AuthorizationManager: authorization not found");
        _;
    }

    modifier onlyLicensor(uint256 authId) {
        require(
            _authorizations[authId].licensor == msg.sender ||
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "AuthorizationManager: not the licensor"
        );
        _;
    }

    modifier onlyActive(uint256 authId) {
        require(_authorizations[authId].active, "AuthorizationManager: not active");
        _;
    }

    // ============ 核心功能 ============

    /**
     * @dev 创建版权授权
     * @param copyrightId 版权记录ID
     * @param licensee 被授权人地址
     * @param licenseType 授权类型
     * @param durationDays 授权天数 (0=永久)
     * @return authId 授权ID
     */
    function createAuthorization(
        uint256 copyrightId,
        address licensee,
        LicenseType licenseType,
        uint256 durationDays
    )
        external
        payable
        nonReentrant
        returns (uint256 authId)
    {
        require(licensee != address(0), "AuthorizationManager: invalid licensee");
        require(licensee != msg.sender, "AuthorizationManager: cannot authorize to self");

        _authIdCounter++;
        authId = _authIdCounter;

        uint256 endTime = 0;
        if (durationDays > 0) {
            endTime = block.timestamp + (durationDays * 1 days);
        }

        Authorization storage auth = _authorizations[authId];
        auth.id = authId;
        auth.copyrightId = copyrightId;
        auth.licensor = msg.sender;
        auth.licensee = licensee;
        auth.licenseType = licenseType;
        auth.fee = msg.value;
        auth.startTime = block.timestamp;
        auth.endTime = endTime;
        auth.active = true;
        auth.createdAt = block.timestamp;

        _copyrightAuthorizations[copyrightId].push(authId);
        _licenseeAuthorizations[licensee].push(authId);
        _allAuthIds.push(authId);

        emit AuthorizationCreated(authId, copyrightId, msg.sender, licensee, licenseType, msg.value);

        return authId;
    }

    /**
     * @dev 撤销授权
     */
    function revokeAuthorization(
        uint256 authId
    )
        external
        authExists(authId)
        onlyLicensor(authId)
        onlyActive(authId)
    {
        _authorizations[authId].active = false;

        emit AuthorizationRevoked(authId, msg.sender);
    }

    /**
     * @dev 发放授权许可证书
     * @param authId 授权ID
     * @param licenseURI 许可证书URI
     * @return licenseId 许可ID
     */
    function issueLicense(
        uint256 authId,
        string calldata licenseURI
    )
        external
        authExists(authId)
        onlyLicensor(authId)
        onlyActive(authId)
        returns (uint256 licenseId)
    {
        _licenseIdCounter++;
        licenseId = _licenseIdCounter;

        License storage lic = _licenses[licenseId];
        lic.id = licenseId;
        lic.authorizationId = authId;
        lic.licensee = _authorizations[authId].licensee;
        lic.licenseURI = licenseURI;
        lic.issuedAt = block.timestamp;
        lic.valid = true;

        emit LicenseIssued(licenseId, authId, lic.licensee, licenseURI);

        return licenseId;
    }

    /**
     * @dev 撤销许可证书
     */
    function revokeLicense(
        uint256 licenseId
    )
        external
    {
        require(_licenses[licenseId].id > 0, "AuthorizationManager: license not found");
        uint256 authId = _licenses[licenseId].authorizationId;
        require(
            _authorizations[authId].licensor == msg.sender ||
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "AuthorizationManager: not authorized"
        );

        _licenses[licenseId].valid = false;
        emit LicenseRevoked(licenseId);
    }

    // ============ 查询功能 ============

    /**
     * @dev 获取授权详情
     */
    function getAuthorization(
        uint256 authId
    )
        external
        view
        authExists(authId)
        returns (Authorization memory)
    {
        return _authorizations[authId];
    }

    /**
     * @dev 获取许可详情
     */
    function getLicense(
        uint256 licenseId
    )
        external
        view
        returns (License memory)
    {
        require(_licenses[licenseId].id > 0, "AuthorizationManager: license not found");
        return _licenses[licenseId];
    }

    /**
     * @dev 检查授权是否有效
     */
    function isAuthorizationValid(
        uint256 authId
    )
        external
        view
        authExists(authId)
        returns (bool)
    {
        Authorization storage auth = _authorizations[authId];
        if (!auth.active) return false;
        if (auth.endTime > 0 && block.timestamp > auth.endTime) return false;
        return true;
    }

    /**
     * @dev 检查许可是否有效
     */
    function isLicenseValid(
        uint256 licenseId
    )
        external
        view
        returns (bool)
    {
        License storage lic = _licenses[licenseId];
        if (lic.id == 0 || !lic.valid) return false;

        Authorization storage auth = _authorizations[lic.authorizationId];
        if (!auth.active) return false;
        if (auth.endTime > 0 && block.timestamp > auth.endTime) return false;

        return true;
    }

    /**
     * @dev 获取版权的授权列表
     */
    function getCopyrightAuthorizations(
        uint256 copyrightId
    )
        external
        view
        returns (uint256[] memory)
    {
        return _copyrightAuthorizations[copyrightId];
    }

    /**
     * @dev 获取被授权人的授权列表
     */
    function getLicenseeAuthorizations(
        address licensee
    )
        external
        view
        returns (uint256[] memory)
    {
        return _licenseeAuthorizations[licensee];
    }

    /**
     * @dev 分页获取全部授权
     */
    function getAuthorizationsPaginated(
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (
            Authorization[] memory records,
            uint256 total
        )
    {
        total = _allAuthIds.length;
        if (offset >= total) {
            return (new Authorization[](0), total);
        }

        uint256 end = offset + limit;
        if (end > total) end = total;
        uint256 size = end - offset;

        records = new Authorization[](size);
        for (uint256 i = 0; i < size; i++) {
            records[i] = _authorizations[_allAuthIds[offset + i]];
        }
        return (records, total);
    }

    // ============ 提款功能 ============

    /**
     * @dev 授权人提取授权费
     */
    function withdrawFees(
        uint256 authId
    )
        external
        authExists(authId)
        onlyLicensor(authId)
        nonReentrant
    {
        Authorization storage auth = _authorizations[authId];
        uint256 amount = auth.fee;
        require(amount > 0, "AuthorizationManager: no fees to withdraw");
        auth.fee = 0;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        require(success, "AuthorizationManager: withdraw failed");
    }

    // ============ 管理功能 ============

    /**
     * @dev 授予仲裁者角色
     */
    function grantArbiterRole(address account)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        grantRole(ARBITER_ROLE, account);
    }

    /**
     * @dev 获取全部授权数量
     */
    function getTotalAuthorizations() external view returns (uint256) {
        return _allAuthIds.length;
    }
}

contracts/CopyrightNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title CopyrightNFT
 * @dev 链创守护 - AIGC作品版权NFT合约 (ERC-721)
 */
contract CopyrightNFT is ERC721, Ownable, AccessControl, ReentrancyGuard {

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    struct NFTMetadata {
        uint256 tokenId;
        uint256 copyrightId;
        string ipfsCid;
        address creator;
        uint256 royaltyRate;
        uint256 mintedAt;
    }

    uint256 private _tokenIdCounter;

    mapping(uint256 => NFTMetadata) private _nftMetadata;
    mapping(uint256 => uint256) private _copyrightToToken;
    mapping(uint256 => uint256) private _royaltyRates;

    string private constant _NAME = "CopyrightGuard NFT";
    string private constant _SYMBOL = "CGNFT";

    event NFTMinted(uint256 indexed tokenId, uint256 indexed copyrightId, address indexed creator, string ipfsCid, string tokenURI);
    event NFTRoyaltySet(uint256 indexed tokenId, uint256 royaltyRate);

    constructor() ERC721(_NAME, _SYMBOL) Ownable() {
        _transferOwnership(msg.sender);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
    }

    function mintCopyrightNFT(
        address to,
        uint256 copyrightId,
        string calldata ipfsCid,
        string calldata tokenURI_,
        uint256 royaltyRate
    )
        public
        onlyRole(MINTER_ROLE)
        nonReentrant
        returns (uint256)
    {
        require(to != address(0), "Zero address");
        require(bytes(ipfsCid).length > 0, "Empty CID");
        require(royaltyRate <= 10000, "Invalid royalty");
        require(_copyrightToToken[copyrightId] == 0, "Already minted");

        _tokenIdCounter++;
        uint256 tokenId = _tokenIdCounter;

        _safeMint(to, tokenId);
        // 简化版：tokenURI 存入 mapping（不用 URIStorage）
        _setTokenURI(tokenId, tokenURI_);

        NFTMetadata storage meta = _nftMetadata[tokenId];
        meta.tokenId = tokenId;
        meta.copyrightId = copyrightId;
        meta.ipfsCid = ipfsCid;
        meta.creator = to;
        meta.royaltyRate = royaltyRate;
        meta.mintedAt = block.timestamp;

        _copyrightToToken[copyrightId] = tokenId;
        _royaltyRates[tokenId] = royaltyRate;

        emit NFTMinted(tokenId, copyrightId, to, ipfsCid, tokenURI_);
        return tokenId;
    }

    // 存储 tokenURI 的 mapping
    mapping(uint256 => string) private _tokenURIs;

    function _setTokenURI(uint256 tokenId, string memory _tokenURI) internal {
        _tokenURIs[tokenId] = _tokenURI;
    }

    function tokenURI(uint256 tokenId) public view virtual override returns (string memory) {
        string memory uri = _tokenURIs[tokenId];
        if (bytes(uri).length > 0) return uri;
        return super.tokenURI(tokenId);
    }

    function getNFTMetadata(uint256 tokenId) external view returns (NFTMetadata memory) {
        require(_exists(tokenId), "Token not exists");
        return _nftMetadata[tokenId];
    }

    function getTokenByCopyright(uint256 copyrightId) external view returns (uint256) {
        uint256 tokenId = _copyrightToToken[copyrightId];
        require(tokenId > 0, "Not minted");
        return tokenId;
    }

    function getRoyaltyRate(uint256 tokenId) external view returns (uint256) {
        return _royaltyRates[tokenId];
    }

    function getCreatorNFTs(address creator) external view returns (uint256[] memory) {
        uint256 balance = balanceOf(creator);
        uint256[] memory tokens = new uint256[](balance);
        uint256 idx = 0;
        for (uint256 i = 1; i <= _tokenIdCounter && idx < balance; i++) {
            if (_exists(i) && ownerOf(i) == creator) {
                tokens[idx++] = i;
            }
        }
        return tokens;
    }

    function getCurrentTokenId() external view returns (uint256) { return _tokenIdCounter; }
    function isCopyrightMinted(uint256 copyrightId) external view returns (bool) { return _copyrightToToken[copyrightId] > 0; }

    function setRoyaltyRate(uint256 tokenId, uint256 royaltyRate) external {
        require(_exists(tokenId) && ownerOf(tokenId) == msg.sender, "Not owner");
        require(royaltyRate <= 10000, "Invalid rate");
        _royaltyRates[tokenId] = royaltyRate;
        if (_nftMetadata[tokenId].tokenId > 0) _nftMetadata[tokenId].royaltyRate = royaltyRate;
        emit NFTRoyaltySet(tokenId, royaltyRate);
    }

    function grantMinterRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) { grantRole(MINTER_ROLE, account); }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function _burn(uint256 tokenId) internal override {
        super._burn(tokenId);
        delete _tokenURIs[tokenId];
    }
}

contracts/CopyrightRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title CopyrightRegistry
 * @dev 链创守护 - AIGC作品版权存证合约
 * @notice 提供作品版权存证、时间戳记录、版权查询功能
 */
contract CopyrightRegistry is Ownable, AccessControl, ReentrancyGuard, Pausable {

    // ============ 角色定义 ============
    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");
    bytes32 public constant VERIFIER_ROLE = keccak256("VERIFIER_ROLE");

    // ============ 数据结构 ============

    /// @dev 版权记录结构体
    struct CopyrightRecord {
        uint256 id;                 // 版权记录ID
        address creator;            // 创作者钱包地址
        string fileHash;            // 作品文件SHA256哈希
        string ipfsCid;             // IPFS内容标识符
        string metadataCid;         // 元数据IPFS CID
        string certCid;             // 版权证书IPFS CID
        string workTitle;           // 作品标题
        string workType;            // 作品类型 (IMAGE/VIDEO/MUSIC/TEXT)
        uint256 timestamp;          // 存证时间戳
        bool exists;                // 记录是否存在
    }

    /// @dev 侵权报告结构体
    struct InfringementReport {
        uint256 id;
        uint256 originalCopyrightId;    // 原始版权记录ID
        string infringingFileHash;      // 侵权作品哈希
        string infringingIpfsCid;       // 侵权作品IPFS CID
        uint256 similarityScore;        // 相似度分数 (0-10000, 即0%-100%)
        address reporter;               // 报告人
        ReportStatus status;            // 报告状态
        uint256 timestamp;
    }

    enum ReportStatus {
        PENDING,      // 待处理
        CONFIRMED,    // 已确认侵权
        DISMISSED     // 已驳回
    }

    // ============ 状态变量 ============

    uint256 private _copyrightIdCounter;
    uint256 private _reportIdCounter;

    // 版权记录映射: copyrightId => CopyrightRecord
    mapping(uint256 => CopyrightRecord) private _copyrightRecords;

    // 文件哈希 => 版权记录ID (快速查重)
    mapping(string => uint256) private _fileHashToId;

    // 创作者地址 => 版权记录ID列表
    mapping(address => uint256[]) private _creatorCopyrights;

    // 侵权报告映射
    mapping(uint256 => InfringementReport) private _infringementReports;

    // 全部版权记录ID列表
    uint256[] private _allCopyrightIds;

    // ============ 事件 ============

    event CopyrightRegistered(
        uint256 indexed copyrightId,
        address indexed creator,
        string fileHash,
        string ipfsCid,
        uint256 timestamp
    );

    event CopyrightUpdated(
        uint256 indexed copyrightId,
        string newMetadataCid
    );

    event CopyrightRevoked(
        uint256 indexed copyrightId,
        address indexed creator
    );

    event InfringementReported(
        uint256 indexed reportId,
        uint256 indexed originalCopyrightId,
        string infringingFileHash,
        uint256 similarityScore
    );

    event InfringementResolved(
        uint256 indexed reportId,
        ReportStatus status
    );

    // ============ 构造函数 ============

    constructor() Ownable() {
        _transferOwnership(msg.sender);
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(REGISTRAR_ROLE, msg.sender);
        _grantRole(VERIFIER_ROLE, msg.sender);
    }

    // ============ 修饰器 ============

    modifier copyrightExists(uint256 copyrightId) {
        require(_copyrightRecords[copyrightId].exists, "CopyrightRegistry: copyright not found");
        _;
    }

    modifier onlyCreator(uint256 copyrightId) {
        require(
            _copyrightRecords[copyrightId].creator == msg.sender ||
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender),
            "CopyrightRegistry: not the creator"
        );
        _;
    }

    // ============ 核心功能 ============

    /**
     * @dev 注册新的版权存证
     * @param fileHash 作品文件SHA256哈希
     * @param ipfsCid 作品IPFS CID
     * @param metadataCid 元数据IPFS CID
     * @param workTitle 作品标题
     * @param workType 作品类型
     * @return copyrightId 版权记录ID
     */
    function registerCopyright(
        string calldata fileHash,
        string calldata ipfsCid,
        string calldata metadataCid,
        string calldata workTitle,
        string calldata workType
    )
        external
        whenNotPaused
        nonReentrant
        returns (uint256 copyrightId)
    {
        require(bytes(fileHash).length > 0, "CopyrightRegistry: empty file hash");
        require(bytes(ipfsCid).length > 0, "CopyrightRegistry: empty IPFS CID");
        require(_fileHashToId[fileHash] == 0, "CopyrightRegistry: file already registered");

        _copyrightIdCounter++;
        copyrightId = _copyrightIdCounter;

        CopyrightRecord storage record = _copyrightRecords[copyrightId];
        record.id = copyrightId;
        record.creator = msg.sender;
        record.fileHash = fileHash;
        record.ipfsCid = ipfsCid;
        record.metadataCid = metadataCid;
        record.certCid = "";
        record.workTitle = workTitle;
        record.workType = workType;
        record.timestamp = block.timestamp;
        record.exists = true;

        _fileHashToId[fileHash] = copyrightId;
        _creatorCopyrights[msg.sender].push(copyrightId);
        _allCopyrightIds.push(copyrightId);

        emit CopyrightRegistered(copyrightId, msg.sender, fileHash, ipfsCid, block.timestamp);

        return copyrightId;
    }

    /**
     * @dev 更新版权证书CID
     * @param copyrightId 版权记录ID
     * @param certCid 版权证书IPFS CID
     */
    function updateCertificateCid(
        uint256 copyrightId,
        string calldata certCid
    )
        external
        copyrightExists(copyrightId)
        onlyCreator(copyrightId)
    {
        _copyrightRecords[copyrightId].certCid = certCid;
        emit CopyrightUpdated(copyrightId, certCid);
    }

    /**
     * @dev 撤销版权存证
     * @param copyrightId 版权记录ID
     */
    function revokeCopyright(
        uint256 copyrightId
    )
        external
        copyrightExists(copyrightId)
        onlyCreator(copyrightId)
    {
        CopyrightRecord storage record = _copyrightRecords[copyrightId];
        string memory fileHash = record.fileHash;

        delete _fileHashToId[fileHash];
        record.exists = false;

        emit CopyrightRevoked(copyrightId, msg.sender);
    }

    // ============ 查询功能 ============

    /**
     * @dev 根据版权ID获取版权详情
     */
    function getCopyright(
        uint256 copyrightId
    )
        external
        view
        copyrightExists(copyrightId)
        returns (CopyrightRecord memory)
    {
        return _copyrightRecords[copyrightId];
    }

    /**
     * @dev 根据文件哈希查询版权记录ID
     */
    function getCopyrightIdByHash(
        string calldata fileHash
    )
        external
        view
        returns (uint256)
    {
        uint256 id = _fileHashToId[fileHash];
        require(id > 0, "CopyrightRegistry: not registered");
        return id;
    }

    /**
     * @dev 检查文件是否已注册版权
     */
    function isCopyrightRegistered(
        string calldata fileHash
    )
        external
        view
        returns (bool)
    {
        return _fileHashToId[fileHash] > 0;
    }

    /**
     * @dev 获取创作者的版权记录列表
     */
    function getCreatorCopyrights(
        address creator
    )
        external
        view
        returns (uint256[] memory)
    {
        return _creatorCopyrights[creator];
    }

    /**
     * @dev 获取创作者版权记录数量
     */
    function getCreatorCopyrightCount(
        address creator
    )
        external
        view
        returns (uint256)
    {
        return _creatorCopyrights[creator].length;
    }

    /**
     * @dev 获取全部版权记录数量
     */
    function getTotalCopyrights()
        external
        view
        returns (uint256)
    {
        return _allCopyrightIds.length;
    }

    /**
     * @dev 分页获取版权记录列表
     */
    function getCopyrightsPaginated(
        uint256 offset,
        uint256 limit
    )
        external
        view
        returns (
            CopyrightRecord[] memory records,
            uint256 total
        )
    {
        total = _allCopyrightIds.length;
        if (offset >= total) {
            return (new CopyrightRecord[](0), total);
        }

        uint256 end = offset + limit;
        if (end > total) {
            end = total;
        }
        uint256 resultSize = end - offset;

        records = new CopyrightRecord[](resultSize);
        for (uint256 i = 0; i < resultSize; i++) {
            records[i] = _copyrightRecords[_allCopyrightIds[offset + i]];
        }

        return (records, total);
    }

    // ============ 侵权报告功能 ============

    /**
     * @dev 提交侵权报告
     * @param originalCopyrightId 原始版权记录ID
     * @param infringingFileHash 疑似侵权作品哈希
     * @param infringingIpfsCid 疑似侵权作品IPFS CID
     * @param similarityScore 相似度分数 (0-10000)
     * @return reportId 报告ID
     */
    function reportInfringement(
        uint256 originalCopyrightId,
        string calldata infringingFileHash,
        string calldata infringingIpfsCid,
        uint256 similarityScore
    )
        external
        copyrightExists(originalCopyrightId)
        returns (uint256 reportId)
    {
        require(similarityScore <= 10000, "CopyrightRegistry: invalid score");

        _reportIdCounter++;
        reportId = _reportIdCounter;

        InfringementReport storage report = _infringementReports[reportId];
        report.id = reportId;
        report.originalCopyrightId = originalCopyrightId;
        report.infringingFileHash = infringingFileHash;
        report.infringingIpfsCid = infringingIpfsCid;
        report.similarityScore = similarityScore;
        report.reporter = msg.sender;
        report.status = ReportStatus.PENDING;
        report.timestamp = block.timestamp;

        emit InfringementReported(
            reportId,
            originalCopyrightId,
            infringingFileHash,
            similarityScore
        );

        return reportId;
    }

    /**
     * @dev 解决侵权报告 (管理员/验证者调用)
     */
    function resolveInfringement(
        uint256 reportId,
        ReportStatus resolution
    )
        external
        onlyRole(VERIFIER_ROLE)
    {
        require(
            _infringementReports[reportId].id > 0,
            "CopyrightRegistry: report not found"
        );
        require(
            _infringementReports[reportId].status == ReportStatus.PENDING,
            "CopyrightRegistry: already resolved"
        );

        _infringementReports[reportId].status = resolution;

        emit InfringementResolved(reportId, resolution);
    }

    /**
     * @dev 获取侵权报告详情
     */
    function getInfringementReport(
        uint256 reportId
    )
        external
        view
        returns (InfringementReport memory)
    {
        require(_infringementReports[reportId].id > 0, "CopyrightRegistry: report not found");
        return _infringementReports[reportId];
    }

    // ============ 管理功能 ============

    /**
     * @dev 暂停合约
     */
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    /**
     * @dev 恢复合约
     */
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    /**
     * @dev 授予注册者角色
     */
    function grantRegistrarRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        grantRole(REGISTRAR_ROLE, account);
    }

    /**
     * @dev 授予验证者角色
     */
    function grantVerifierRole(address account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        grantRole(VERIFIER_ROLE, account);
    }
}

